struct PaneListState {
    tree: ScrollHandle,
    agents: ScrollHandle,
    backlog: ScrollHandle,
    tree_selected: usize,
    tree_anchor: Option<PathBuf>,
    agent_selected: AgentRow,
    main_selection: AgentRow,
    backlog_selection: AgentRow,
    backlog_focused: bool,
}
impl PaneListState {
    fn new(model: &Workspace) -> Self {
        Self {
            tree: ScrollHandle::new(),
            agents: ScrollHandle::new(),
            backlog: ScrollHandle::new(),
            tree_selected: model.tree_selected,
            tree_anchor: model.tree_anchor.clone(),
            agent_selected: model.selected.clone(),
            main_selection: model.main_selection.clone(),
            backlog_selection: model.backlog_selection.clone(),
            backlog_focused: model.surface == Surface::Backlog,
        }
    }
    fn duplicate(&self) -> Self {
        let copy = Self {
            tree: ScrollHandle::new(),
            agents: ScrollHandle::new(),
            backlog: ScrollHandle::new(),
            tree_selected: self.tree_selected,
            tree_anchor: self.tree_anchor.clone(),
            agent_selected: self.agent_selected.clone(),
            main_selection: self.main_selection.clone(),
            backlog_selection: self.backlog_selection.clone(),
            backlog_focused: self.backlog_focused,
        };
        copy.tree.set_offset(self.tree.offset());
        copy.agents.set_offset(self.agents.offset());
        copy.backlog.set_offset(self.backlog.offset());
        copy
    }
}
